// Command gen projects the Go capability catalog into the frontend module.
//
// The Go catalog is the single source of truth because it is the actual
// authorization boundary; the frontend only mirrors it for routing and UI. The
// generated file is committed so `pnpm build` never needs a Go toolchain, and
// gen_test.go fails when it drifts.
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"main/internal/authorization"
)

// outputRelativePath is relative to the repository root.
const outputRelativePath = "web/src/lib/auth/capabilities.generated.ts"

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "generate capabilities: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	payload, err := render(authorization.All())
	if err != nil {
		return err
	}

	path, err := outputPath()
	if err != nil {
		return err
	}

	// 0o600 is enough: git only records the executable bit, and the file must not
	// be world-writable while it is regenerated.
	if writeErr := os.WriteFile(path, payload, 0o600); writeErr != nil {
		return fmt.Errorf("write %s: %w", path, writeErr)
	}

	fmt.Printf("generated %s\n", path)
	return nil
}

// render builds the TypeScript module. It must stay deterministic: gen_test.go
// compares its output byte for byte against the committed file.
func render(capabilities []authorization.Capability) ([]byte, error) {
	if len(capabilities) == 0 {
		return nil, errors.New("capability catalog is empty")
	}

	identifiers := make(map[string]authorization.Capability, len(capabilities))
	names := make([]string, len(capabilities))
	for index, capability := range capabilities {
		name, err := tsIdentifier(string(capability))
		if err != nil {
			return nil, err
		}
		if previous, duplicate := identifiers[name]; duplicate {
			return nil, fmt.Errorf("capabilities %q and %q both map to the identifier %q", previous, capability, name)
		}
		identifiers[name] = capability
		names[index] = name
	}

	var builder strings.Builder
	builder.WriteString("// Code generated by internal/authorization/gen. DO NOT EDIT.\n")
	builder.WriteString("// Regenerate with: go generate ./internal/authorization\n")
	builder.WriteString("//\n")
	builder.WriteString("// The Go capability catalog is the single source of truth. This module only\n")
	builder.WriteString("// mirrors it so the frontend cannot drift: every capability string, its type and\n")
	builder.WriteString("// its named handle come from the same declaration.\n\n")
	builder.WriteString("import { z } from 'zod'\n\n")

	builder.WriteString("export const capabilitySchema = z.enum([\n")
	for _, capability := range capabilities {
		fmt.Fprintf(&builder, "  '%s',\n", capability)
	}
	builder.WriteString("])\n\n")

	builder.WriteString("export type Capability = z.infer<typeof capabilitySchema>\n\n")

	builder.WriteString("export const CAPABILITY = {\n")
	for index, capability := range capabilities {
		fmt.Fprintf(&builder, "  %s: '%s',\n", names[index], capability)
	}
	builder.WriteString("} as const satisfies Record<string, Capability>\n")

	return []byte(builder.String()), nil
}

// tsIdentifier turns "management.system_logs.read" into "managementSystemLogsRead".
// The mapping is fixed so the generated object keeps stable, greppable names.
func tsIdentifier(capability string) (string, error) {
	if strings.Contains(capability, "\n") || strings.Contains(capability, "\r") {
		return "", fmt.Errorf("capability %q must be a single line", capability)
	}

	segments := strings.FieldsFunc(capability, func(r rune) bool {
		return r == '.' || r == '_' || r == '-' || r == ' '
	})
	if len(segments) == 0 {
		return "", fmt.Errorf("capability %q has no identifier segments", capability)
	}

	var builder strings.Builder
	for index, segment := range segments {
		lowered := strings.ToLower(segment)
		if index == 0 {
			builder.WriteString(lowered)
			continue
		}
		builder.WriteString(strings.ToUpper(lowered[:1]))
		builder.WriteString(lowered[1:])
	}

	name := builder.String()
	if name == "" || name[0] < 'a' || name[0] > 'z' {
		return "", fmt.Errorf("capability %q maps to the invalid TypeScript identifier %q", capability, name)
	}
	for _, r := range name {
		if (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') && (r < '0' || r > '9') {
			return "", fmt.Errorf("capability %q maps to the invalid TypeScript identifier %q", capability, name)
		}
	}

	return name, nil
}

// outputPath resolves the repository root from this file's location so the
// generator works regardless of the caller's working directory.
func outputPath() (string, error) {
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		return "", errors.New("cannot resolve generator source path")
	}

	// <root>/internal/authorization/gen/main.go -> <root>
	root := filepath.Join(filepath.Dir(thisFile), "..", "..", "..")
	return filepath.Join(root, filepath.FromSlash(outputRelativePath)), nil
}
